${context}

Question: ${question}`;

// Step 4: call model
  const response = await anthropic.messages.create({
    model: "claude-sonnet-4-6",
    messages: [{ role: "user", content: prompt }],
    max_tokens: 1024,
  });

// Step 5: parse + return
  return response.content[0].text;
